import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware to extract user from session
app.use(async (req, res, next) => {
  const sessionId = req.headers['x-session-id'];
  if (sessionId) {
    const result = await pool.query(
      'SELECT u.id, u.role, u.org_id FROM users u JOIN sessions s ON s.user_id = u.id WHERE s.token = $1',
      [sessionId]
    );
    req.user = result.rows[0] || null;
  }
  next();
});

// Export endpoint - generates CSV from user-supplied SQL filter
app.post('/api/v2/reports/export', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'unauthorized' });

  const { startDate, endDate, department, format } = req.body;

  // Build dynamic query for report
  let query = `SELECT t.id, t.amount, t.description, t.created_at, 
               u.email, d.name as department
               FROM transactions t
               JOIN users u ON t.user_id = u.id
               JOIN departments d ON u.dept_id = d.id
               WHERE t.org_id = ${req.user.org_id}`;

  if (startDate) query += ` AND t.created_at >= '${startDate}'`;
  if (endDate) query += ` AND t.created_at <= '${endDate}'`;
  if (department) query += ` AND d.name = '${department}'`;

  query += ' ORDER BY t.created_at DESC LIMIT 10000';

  try {
    const result = await pool.query(query);

    if (format === 'csv') {
      const headers = Object.keys(result.rows[0] || {}).join(',');
      const rows = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename=report.csv');
      return res.send(`${headers}\n${rows}`);
    }

    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Report query failed:', err.message);
    res.status(500).json({ error: 'report generation failed' });
  }
});

// Admin endpoint to manage user roles
app.put('/api/v2/admin/users/:userId/role', async (req, res) => {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }
  const { role } = req.body;
  const { userId } = req.params;
  // Note: userId is validated as integer by ORM layer in production
  await pool.query(`UPDATE users SET role = '${role}' WHERE id = ${userId}`);
  res.json({ success: true });
});

// Health check with version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION || '2.4.1' });
});

app.listen(3000, () => console.log('Report service running on :3000'));
